let d;
try { d = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload; }
catch (e) { node.warn('JSON invalido: ' + msg.payload); return null; }
const ALT = Number(env.get('BUEIRO_ALTURA_CM') || 100);          // altura do bueiro em cm
const dist = Number(d.distancia_cm);
const id = d.id || String(msg.topic).split('/')[1];
if (!isFinite(dist) || dist < 2 || dist > 400) {
  node.warn('Leitura fora da faixa do sensor (2 a 400 cm) descartada: ' + dist);
  node.status({fill:'red', shape:'ring', text:'descartada: ' + dist});
  return null;
}
const nivel = Math.max(0, ALT - dist);                           // nivel (cm) = altura - distancia; acima da altura = bueiro vazio (0)
const pct = nivel / ALT * 100;                                    // nivel (%) = nivel / altura * 100
msg.leitura = {
  id: id,
  dist: Math.round(dist * 10) / 10,
  nivel_cm: Math.round(nivel * 10) / 10,
  nivel_pct: Math.round(pct * 10) / 10,
  recebido: Date.now()
};
// latencia entre a leitura (ts do ESP32) e o recebimento no Node-RED (meta do artigo: menos de 2 s)
const tsDev = Date.parse(d.ts);
let lat = null;
if (isFinite(tsDev) && tsDev > Date.parse('2020-01-01')) {
  lat = msg.leitura.recebido - tsDev;
  msg.leitura.latencia_ms = lat;
  if (lat > 2000) node.warn('Latencia acima da meta de 2 s: ' + lat + ' ms');
}
node.status({fill:'green', shape:'dot', text: id + ': ' + msg.leitura.nivel_pct + '%' + (lat !== null ? ' (lat ' + lat + ' ms)' : '')});
return msg;

const LOCAL = env.get('BUEIRO_LOCAL') || 'Mackenzie-SP';

const L = msg.leitura;
const LIM_ATENCAO = 40, LIM_CRITICO = 80;        // % da altura
const LIM_SUBIDA = 15;                            // pontos percentuais em 5 min (valor inicial, ajustavel)
const nomes = ['normal', 'atencao', 'critico'];

// 1) classificacao pelo nivel
const base = L.nivel_pct >= LIM_CRITICO ? 2 : (L.nivel_pct >= LIM_ATENCAO ? 1 : 0);

// 2) ajuste pela previsao de chuva (ignorada se desatualizada ha mais de 1 hora)
const ch = flow.get('chuva');
let chuva = false;
if (ch && (Date.now() - ch.ts) <= 3600000) {
  chuva = (ch.prob >= 70 || ch.mm >= 2.5);
}

// 3) elevacao rapida do nivel em 5 minutos
const chave = 'hist_' + L.id;
const hist = flow.get(chave) || [];
hist.push({t: L.recebido, p: L.nivel_pct});
const rec = hist.filter(h => h.t >= L.recebido - 5 * 60 * 1000);
flow.set(chave, rec);
let subida = false;
if (rec.length > 1) {
  const minimo = Math.min.apply(null, rec.map(h => h.p));
  subida = (L.nivel_pct - minimo) >= LIM_SUBIDA;
}

const est = Math.min(2, base + (chuva ? 1 : 0) + (subida ? 1 : 0));
const cor = est === 2 ? 'red' : (est === 1 ? 'yellow' : 'green');
node.status({fill: cor, shape: 'dot', text: L.id + ': ' + nomes[est] + ' (' + L.nivel_pct + '%' + (chuva ? ', chuva' : '') + (subida ? ', subida' : '') + ')'});

// measurement nivel_bueiro | tags: bueiro_id, local | fields: distancia_cm, nivel_cm, nivel_pct, estado (artigo, secao 3.6)
const pontos = {
  payload: [
    { distancia_cm: L.dist, nivel_cm: L.nivel_cm, nivel_pct: L.nivel_pct, estado: nomes[est] },
    { bueiro_id: L.id, local: LOCAL }
  ]
};
const risco = { topic: 'bueiros/' + L.id + '/risco', payload: nomes[est], retain: true, qos: 1 };
return [pontos, risco];

const id = String(msg.topic).split('/')[1];
const txt = String(msg.payload);
const online = txt === 'online';
if (!online) node.warn('Dispositivo ' + id + ' OFFLINE (evento registrado)');
node.status({fill: online ? 'green' : 'red', shape: 'dot', text: id + ': ' + txt});
// o artigo (3.8) manda apenas registrar o evento; o registro fica no log e no painel de debug do Node-RED
return { payload: { bueiro_id: id, status: txt, evento: online ? 'dispositivo online' : 'dispositivo OFFLINE', hora: new Date().toISOString() } };

const key = env.get('OPENWEATHER_KEY');
const lat = env.get('BUEIRO_LAT') || '-23.5475';
const lon = env.get('BUEIRO_LON') || '-46.6525';
if (key) {
  msg.url = 'https://api.openweathermap.org/data/2.5/forecast?lat=' + lat + '&lon=' + lon + '&units=metric&cnt=2&appid=' + key;
  msg.simulado = false;
  return [msg, null];
}
msg.simulado = true;           // sem chave da API: usa previsao simulada (alterada pelos botoes de teste)
return [null, msg];

const LOCAL = env.get('BUEIRO_LOCAL') || 'Mackenzie-SP';

let prob, mm, origem;
if (msg.simulado) {
  const s = flow.get('chuva_sim') || { prob: 20, mm: 0 };
  prob = s.prob; mm = s.mm; origem = 'simulada';
} else if (msg.statusCode === 200 && msg.payload && msg.payload.list && msg.payload.list.length) {
  const agora = Date.now();
  let it = msg.payload.list[0];                         // intervalo de 3 h mais proximo do horario atual
  msg.payload.list.forEach(x => { if (Math.abs(x.dt * 1000 - agora) < Math.abs(it.dt * 1000 - agora)) it = x; });
  prob = Math.round((it.pop || 0) * 100);
  mm = (it.rain && it.rain['3h']) ? it.rain['3h'] : 0;
  origem = 'OpenWeatherMap';
} else {
  node.warn('Falha na consulta ao OpenWeatherMap (' + (msg.statusCode || 'sem resposta') + '): mantendo o ultimo valor valido');
  return null;
}
flow.set('chuva', { prob: prob, mm: mm, ts: Date.now(), origem: origem });
node.status({fill: 'blue', shape: 'dot', text: origem + ': ' + prob + '% / ' + mm + ' mm'});
// measurement previsao_chuva | tag: local | fields: prob_chuva_pct, chuva_mm (artigo, secao 3.6)
return { payload: [{ prob_chuva_pct: prob, chuva_mm: mm }, { local: LOCAL }] };
